using System;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnDicePlayedEffect", menuName = "Data/Battle/Effects/Enemy/OnDicePlayed Effect")]
public class OnDicePlayedEffect : Effect
{
	[Header("Action Specifics")]
	[SerializeField]
	private OmenLogicActionFace[] omenLogicActionFace;

	[SerializeField]
	private bool necroticPresence;

	[SerializeField]
	[HideIf("necroticPresence")]
	private DiceTier diceTier;

	[NonSerialized]
	private int startingAmount;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = (necroticPresence ? base.localizationManager.GetLocalizedString("NonHexDie") : diceTier.GetLocalizedDiceTierWithDie());
		return string.Concat((startingAmount == -2) ? Smart.Format(base.localizationManager.GetLocalizedString("WheneverYouPlayA"), text) : Smart.Format(base.localizationManager.GetLocalizedString("EveryXDiceTierPlayed"), startingAmount, text), str3: (startingAmount == -2) ? "" : ("\n" + Smart.Format(base.localizationManager.GetLocalizedString("RemainingDice"), amount)), str1: base.localizationManager.GetLocalizedSpace(), str2: GetCurrentDifficultyLevelOmenLogicActionFace().GetActionDescription().LowercaseFirst());
	}

	private OmenLogicActionFace GetCurrentDifficultyLevelOmenLogicActionFace()
	{
		int currentDifficultyLevelModifyEnemiesHighestIndex = ReferenceSingleton<AssetsReference>.Instance.DifficultyLevels.GetCurrentDifficultyLevelModifyEnemiesHighestIndex();
		if (omenLogicActionFace.Length > currentDifficultyLevelModifyEnemiesHighestIndex)
		{
			return omenLogicActionFace[currentDifficultyLevelModifyEnemiesHighestIndex];
		}
		return omenLogicActionFace[omenLogicActionFace.Length - 1];
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		startingAmount = effectAmount;
	}

	public override int ActivateEffectWithSpecificDice(int effectAmount, GameObject effectOwner, Dice dice)
	{
		bool flag = false;
		if ((!necroticPresence) ? (dice.DiceTier == diceTier) : (dice.DiceTier != ReferenceSingleton<AssetsReference>.Instance.HexDieTier && ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance.ActionOwner)))
		{
			UnitEffects unitEffects = effectOwner.GetComponent<UnitEffects>();
			if (effectAmount == -2)
			{
				GetCurrentDifficultyLevelOmenLogicActionFace().ActivateOmen();
			}
			else
			{
				int num = effectAmount - 1;
				if (num == 0)
				{
					GetCurrentDifficultyLevelOmenLogicActionFace().ActivateOmen();
					unitEffects.IsEffectActiveGetEffectInstance(this).StopBlinkingFeedback(shouldForce: true);
					unitEffects.IsEffectActive(this);
					unitEffects.RemoveEffect(this, activateFeedback: false);
					InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
					{
						if (!effectOwner.GetComponent<CorruptionStats>().IsDefeated())
						{
							unitEffects.AddEffect(this, startingAmount, effectFeedback: true, callEffectsCallbacks: false);
						}
					});
					SpawnVFX(4f);
					if (IsVFXEnabled())
					{
						PlayEffectActivationSFX();
					}
				}
				else
				{
					unitEffects.IsEffectActiveAndDecreaseEffect(this, 1);
				}
				if (num == 1)
				{
					unitEffects.IsEffectActiveGetEffectInstance(this).PlayBlinkingFeedback();
				}
			}
		}
		return effectAmount;
	}
}
